// §18.10 item 9: a Worker that bundles several verifiers, as Workers will bundle every
// non-revoked verifier in the catalog (genesis.md §9.2). Copies are generated by
// scripts/make-copies.mjs (the probe build plus a distinct custom section each).
// Startup time is what `wrangler deploy` reports; /run checks each module answers.
import v0 from "../gen/collatio_spike_0.wasm";
import v1 from "../gen/collatio_spike_1.wasm";
import v2 from "../gen/collatio_spike_2.wasm";
import v3 from "../gen/collatio_spike_3.wasm";
import v4 from "../gen/collatio_spike_4.wasm";
import v5 from "../gen/collatio_spike_5.wasm";
import v6 from "../gen/collatio_spike_6.wasm";
import v7 from "../gen/collatio_spike_7.wasm";
import bench from "../../vectors/bench.json";
import { instantiate } from "../../host/collatio.mjs";

const modules = [v0, v1, v2, v3, v4, v5, v6, v7];
const instances = new Map();

export default {
  async fetch(request) {
    const url = new URL(request.url);
    if (url.pathname !== "/run") return new Response("not_found", { status: 404 });
    const which = url.searchParams.get("all") ? modules.map((_, i) => i) : [Number(url.searchParams.get("i") ?? 0)];
    const out = [];
    for (const i of which) {
      if (!instances.has(i)) instances.set(i, instantiate(modules[i]));
      out.push({ i, ok: instances.get(i).call(bench.p256.op, bench.p256.input).ok });
    }
    return new Response(JSON.stringify({ modules: modules.length, out }), { headers: { "content-type": "application/json" } });
  },
};
